<script setup lang="ts">
import { computed } from 'vue';
import { FileCheck2, Send, Download, AlertCircle, CheckCircle2, Clock3, FileText } from 'lucide-vue-next';
import TaskTimeline from './TaskTimeline.vue';
import { campusProject } from './campus-handoff';
import type { CampusTaskStore } from './task-store';
const props=defineProps<{store:CampusTaskStore;busy:boolean}>();
const emit=defineEmits<{generate:[];feedback:[];json:[];html:[];open:[id:string];raw:[id:string]}>();
const report=computed(()=>props.store.acceptance),stale=computed(()=>report.value && report.value.revision!==props.store.revision);
</script>
<template><div class="section-intro"><div><span class="eyebrow">ACCEPTANCE / DELIVERY FEEDBACK</span><h1>汇总已有证据，把结论反馈给交付团队。</h1><p>仅汇总已保存的检查和执行记录，未测项与需整改问题不会被隐藏。</p></div><button class="primary" :disabled="busy" @click="emit('generate')"><FileCheck2 :size="16"/>{{report?'重新汇总验收报告':'汇总验收报告'}}</button></div><div class="acceptance-columns"><div><div v-if="!report" class="panel empty-state"><FileCheck2 :size="43"/><h3>等待手动汇总</h3><p>完成各项测试后，点击汇总验收报告。<br/>也可以提前汇总部分记录，清楚查看剩余未测范围。</p></div><template v-else><div v-if="stale" class="notice" role="status"><AlertCircle :size="16"/>测试记录已更新，请重新汇总后再提交反馈；当前仍为上一份报告快照。</div><section class="panel acceptance-cover"><div class="acceptance-cover-top"><FileCheck2 :size="34"/><div><span class="eyebrow">{{report.id.slice(0,16).toUpperCase()}}</span><h2>智慧校园综合验收报告</h2><p>{{campusProject.brand}} v{{campusProject.version}} · {{new Date(report.at).toLocaleString('zh-CN',{hour12:false})}}</p></div><span class="badge" :class="{issue:report.verdict==='review',good:report.verdict==='passed'}">{{report.verdict==='review'?'存在需整改项':report.verdict==='partial'?'待补测':'本轮已记录检查通过'}}</span></div><div class="acceptance-stat-grid"><article v-for="section in report.sections" :key="section.name"><span>{{section.name}}</span><b>{{section.done}}<em>/ {{section.total}}</em></b><small>{{section.issues ? `${section.issues} 项需整改` : section.done<section.total ? '有未测范围' : '已完成本轮检查'}}</small></article></div><div class="report-source"><CheckCircle2 :size="15"/>UI为人工观察；API、专项与压力为本地模型证据，不等同于真实服务性能验收。</div></section><section class="panel acceptance-list"><div class="panel-heading"><h3><AlertCircle :size="17"/>需整改问题</h3><span>{{report.issues.length}} 项</span></div><ul v-if="report.issues.length"><li v-for="issue in report.issues" :key="issue">{{issue}}</li></ul><p v-else>已执行检查中没有记录需整改项，未测范围请查看下方。</p></section><section class="panel acceptance-list"><div class="panel-heading"><h3><Clock3 :size="17"/>未测范围</h3><span>{{report.untested.length}} 项</span></div><ul v-if="report.untested.length"><li v-for="item in report.untested" :key="item">{{item}}</li></ul><p v-else>本轮计划检查项均已执行。</p></section><section class="panel feedback-panel"><h3><Send :size="18"/>提交验收反馈</h3><p>接收岗位：{{campusProject.frontend}} / {{campusProject.backend}}</p><div class="toolbar-actions"><button class="primary" :disabled="busy || !!stale || !!report.feedback" @click="emit('feedback')"><Send :size="15"/>{{report.feedback?'反馈已提交':'提交验收反馈'}}</button><button class="secondary" :disabled="busy" @click="emit('json')"><Download :size="14"/>导出验收JSON</button><button class="secondary" :disabled="busy" @click="emit('html')"><FileText :size="14"/>下载验收HTML</button></div><div v-if="report.feedback" class="feedback-receipt"><CheckCircle2 :size="18"/><div><b>验收反馈已记录 · {{report.feedback.status}}</b><small>{{report.feedback.id}} · {{new Date(report.feedback.at).toLocaleString('zh-CN',{hour12:false})}}</small><p>{{report.verdict==='review'?'问题已关联到本轮交付，等待整改。':report.verdict==='partial'?'未测范围已随报告反馈，等待补测。':'本轮验收材料已归档到交付任务。'}}</p></div></div></section></template><section class="panel archived-reports"><div class="panel-heading"><h3>本轮原始执行报告</h3><span>{{store.reports.length+(store.uiReports?.length || 0)}} 份</span></div><article v-for="item in store.uiReports || []" :key="item.id"><span class="badge">UI测试</span><div><b>{{item.id.slice(0,11).toUpperCase()}}</b><small>{{new Date(item.at).toLocaleString('zh-CN',{hour12:false})}} · {{item.passed}} 通过 / {{item.issues}} 需整改</small></div><button class="text-button" :disabled="busy" @click="emit('open',item.id)">查看UI报告</button><button class="text-button" :disabled="busy" @click="emit('raw',item.id)">导出UI原始JSON</button></article><article v-for="item in store.reports" :key="item.id"><span class="badge">{{item.kind==='suite'?'API验证':item.kind==='load'?'压力测试':'专项验证'}}</span><div><b>{{item.id.slice(0,8).toUpperCase()}}</b><small>{{new Date(item.startedAt).toLocaleString('zh-CN',{hour12:false})}} · {{item.status==='completed'?'本次执行结束':'阶段记录'}}</small></div><button v-if="item.kind!=='suite'" class="text-button" :disabled="busy" @click="emit('open',item.id)">查看报告</button><button class="text-button" :disabled="busy" @click="emit('raw',item.id)">导出原始JSON</button></article><p v-if="!store.reports.length && !store.uiReports?.length">尚未执行测试，暂无原始报告。</p></section></div><TaskTimeline :entries="store.timeline"/></div></template>
